  @Test("jot output matches the system jot", arguments: systemCases)
  func matchesSystemJot(_ args: [String], _ expected: String, _ status: Int) async throws {
    try await run(status: status, output: expected, args: args)
  }

  // MARK: random output can only be checked for its shape

  @Test(arguments: [(1, 6), (0, 1), (5, 5), (-3, 3), (100, 200)])
  func randomIntegersStayInRange(_ range: (Int, Int)) async throws {
    let (lo, hi) = range
    try await run(args: "-r", "200", "\(lo)", "\(hi)") { po in
      let lines = try po.string(encoded: .utf8).split(separator: "\n")
      #expect(lines.count == 200)
      for l in lines {
        let v = Int(l)
        #expect(v != nil && v! >= lo && v! <= hi, "\(l) is outside \(lo)...\(hi)")
      }
    }
  }

  @Test func randomIntegersCountIsExact() async throws {
    for n in [1, 2, 10, 37] {
      try await run(args: "-r", "\(n)", "1", "9") { po in
        let lines = try po.string(encoded: .utf8).split(separator: "\n")
        #expect(lines.count == n)
      }
    }
  }

  @Test func randomWithDescendingRange() async throws {
    try await run(args: "-r", "100", "9", "1") { po in
      for l in try po.string(encoded: .utf8).split(separator: "\n") {
        let v = Int(l)
        #expect(v != nil && v! >= 1 && v! <= 9)
      }
    }
  }

  @Test func randomFractions() async throws {
    try await run(args: "-r", "-w", "%.2f", "100", "0", "1") { po in
      for l in try po.string(encoded: .utf8).split(separator: "\n") {
        let v = Double(l)
        #expect(v != nil && v! >= 0 && v! <= 1, "\(l)")
      }
    }
  }

  @Test func randomCharacters() async throws {
    try await run(args: "-r", "-c", "200", "97", "122") { po in
      let text = try po.string(encoded: .utf8)
      #expect(text.split(separator: "\n").count == 200)
      #expect(text.allSatisfy { $0 == "\n" || ("a"..."z").contains($0) })
    }
  }

  @Test func aSeedIsAcceptedButHasNoEffect() async throws {
    // jot uses arc4random, which can't be seeded: the seed is checked and then ignored
    try await run(args: "-r", "100", "1", "6", "42") { po in
      let lines = try po.string(encoded: .utf8).split(separator: "\n")
      #expect(lines.count == 100)
      for l in lines {
        let v = Int(l)
        #expect(v != nil && v! >= 1 && v! <= 6)
      }
    }
    try await run(status: 1, args: "-r", "5", "1", "6", "x")
  }

  // MARK: output that is not valid UTF-8

  @Test func characterOutsideAsciiIsItsLastByteAsASignedChar() async throws {
    // "é" is the bytes c3 a9; the last one, a9, is -87 as a signed char, which is printed as a raw byte
    try await run(output: [0xa9, 0x0a, 0xaa, 0x0a, 0xab, 0x0a], args: "-c", "3", "é")
  }

  @Test func charactersAbove127AreRawBytes() async throws {
    try await run(output: [0x7e, 0x0a, 0x7f, 0x0a, 0x80, 0x0a, 0x81, 0x0a], args: "-c", "4", "126")
  }
